/** Reusable user contents inside a caller-owned message row. */
import { Fragment, useEffect, useState } from 'react'
import type { FileAttachmentRef } from '@deepseek-ai/dsh-attachment'
import type { FactoryComponentPropsOf } from '@deepseek-ai/dsh-client-ui-slots'
import { fileExtension, FileTypeIcon, fileSizeText, JsonBlock } from '@deepseek-ai/dsh-client-ui-primitives'
import css from './MessageItem.module.css'
import type { UserContentInjected } from '../contract/slots.ts'

const EMPTY_LABELS: readonly string[] = []

/** Recognize the names generated by the existing composer across both locales. */
function isPastedText(file: FileAttachmentRef): boolean {
  return file.name === '粘贴的文本.txt' || file.name === 'Pasted text.txt'
}

function PastedTextCard({ file, previewPastedText, openPastedText, label, interactive }: {
  readonly file: FileAttachmentRef
  readonly previewPastedText: UserContentInjected['previewPastedText']
  readonly openPastedText: UserContentInjected['openPastedText']
  readonly label: string
  readonly interactive: boolean
}) {
  const [title, setTitle] = useState(label)
  useEffect(() => {
    if (!interactive) return
    let active = true
    void previewPastedText(file).then((value) => { if (active) setTitle(value || label) })
      .catch(() => { if (active) setTitle(label) })
    return () => { active = false }
  }, [file, interactive, label, previewPastedText])
  if (!interactive) return <span className={`${css.fileCard} ${css.pastedTextCard}`}>
    <FileTypeIcon path={file.name} className={css.fileIcon} />
    <span className={css.fileName}>{label}</span>
  </span>
  return <button type="button" className={`${css.fileCard} ${css.pastedTextCard}`}
    title={title} onClick={() => { openPastedText(file) }}>
    <FileTypeIcon path={file.name} className={css.fileIcon} />
    <span className={css.fileName}>{title}</span>
  </button>
}

/**
 * Render prepared text, ordered attachments, and references without message chrome.
 * The caller owns row identity, pending/echo state, time, and message actions.
 * @param props - prepared content, facts, authorized image loader, and framework Factory/locale seats.
 * @returns the content stack using the existing user-message layout.
 */
export function UserContent({ content, loadImage, facts, interactive = false, ellipsis = false,
  previewPastedText, openPastedText, renderSlot, renderFactorySlot, t }:
FactoryComponentPropsOf<'conversation.chat.user.content'> & UserContentInjected) {
  const { text, attachments, extraBlocks, referenceLabels = EMPTY_LABELS } = content
  const compactImages = attachments.length > 1
  const truncated = (total: number): string => t('json.truncated', { total })
  const showBubble = text !== '' || extraBlocks.length > 0
  return (
    <div className={css.userStack}>
      {attachments.length > 0 && (
        <div className={css.attachmentRow} data-message-attachments>
          {attachments.map((attachment, index) => attachment.type === 'image'
            ? (
              <Fragment key={`image:${index}`}>
                {renderSlot('conversation.chat.user.images', {
                  images: [attachment.image], loadImage, align: 'end', compact: compactImages,
                })}
              </Fragment>
            )
            : isPastedText(attachment.file) ? (
              <PastedTextCard key={`file:${index}`} file={attachment.file}
                previewPastedText={previewPastedText} openPastedText={openPastedText}
                label={t('attachment.pastedText')} interactive={interactive} />
            ) : (
              <span key={`file:${index}`} className={css.fileCard} title={attachment.file.name}>
                <FileTypeIcon path={attachment.file.name} className={css.fileIcon} />
                <span className={css.fileContent}>
                  <span className={css.fileName}>{attachment.file.name}</span>
                  <span className={css.fileMeta}>
                    {[fileExtension(attachment.file.name).toUpperCase().slice(0, 8), fileSizeText(attachment.file.bytes)]
                      .filter(Boolean).join(' ')}
                  </span>
                </span>
              </span>
            ))}
        </div>
      )}
      {showBubble && <div className={css.bubble}>
        {renderFactorySlot('conversation.user.text', { text, facts, interactive, ellipsis })}
        {extraBlocks.map((block, index) => (
          <JsonBlock key={index} label={t('message.extraBlock')} payload={block} truncatedLabel={truncated} />
        ))}
      </div>}
      {referenceLabels.length > 0 && (
        <div className={css.referenceSummary}>
          {t('message.referenceSummary', { labels: referenceLabels.join(t('message.referenceSeparator')) })}
        </div>
      )}
    </div>
  )
}
